preConditionHook:
// Level body dominated (Brian's notes P1d, triage row P1). Pane 2. The P1 visit
// scan: a VISIT is a bar kk bars ago, minGap <= kk <= lookback, whose low..high
// range contains the current close (inclusive, el_le/el_ge). At least minVisits
// visits. Body visit: close[0] inside the visit's body, edges included. Passes
// when at least bodyFraction of the visits are body visits. EL's
// MaxList/MinList select between open and close -- tick-grid prices, the scope
// their ACCEPTED row allows -- so plain comparisons stand in. Both operands of
// EL's `and` are pure, so C++ short-circuiting is harmless here.
visitCount = 0;
bodyVisits = 0;
for (kk = (int)minGap; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], close[0]) && el_ge(high[kk], close[0])) {
        visitCount = visitCount + 1;
        bodyTop = open[kk];
        if (close[kk] > bodyTop) bodyTop = close[kk];
        bodyBottom = open[kk];
        if (close[kk] < bodyBottom) bodyBottom = close[kk];
        if (el_ge(close[0], bodyBottom) && el_le(close[0], bodyTop)) bodyVisits = bodyVisits + 1;
    }
}
enoughVisits = el_ge(visitCount, minVisits) && el_gt(visitCount, 0);
